def serp_organic_locations_list(workspace_id, country_code=None, search=None, limit=None, offset=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0555000" if __import__("os").path.isdir("./environment_mix/0555000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(random.choice(alphabet) for _ in range(20))

    def _select_context(workspace_id_value):
        workspaces = _load("workspaces.json")
        api_keys = _load("api_keys.json")
        ws = next((w for w in workspaces if w.get("id") == workspace_id_value), None)
        if ws is None:
            return None, None, _err("NOT_FOUND", "workspace not found", workspace_id=workspace_id_value)
        k_active = next((x for x in api_keys if x.get("workspace_id") == ws.get("id") and x.get("status") == "active"), None)
        k_any = next((x for x in api_keys if x.get("workspace_id") == ws.get("id")), None)
        return ws, (k_active or k_any), None

    # validation
    if not isinstance(workspace_id, str) or not re.match(r"^dfs_ws_[0-9A-Z]{18,}$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id must match ^dfs_ws_[0-9A-Z]{18,}$")
    if country_code is not None:
        if not isinstance(country_code, str) or not re.match(r"^[A-Z]{2}$", country_code):
            return _err("VALIDATION_ERROR", "country_code must be ISO-3166-1 alpha-2 uppercase (e.g., 'US')")
    if search is not None and not isinstance(search, str):
        return _err("VALIDATION_ERROR", "search must be a string")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 1000")
    if offset is None:
        offset = 0
    if not isinstance(offset, int) or offset < 0:
        return _err("VALIDATION_ERROR", "offset must be an integer >= 0")
    if sort_by is None:
        sort_by = "location_name"
    if sort_by not in ("location_name", "location_code", "country_code"):
        return _err("VALIDATION_ERROR", "sort_by must be one of: location_name, location_code, country_code")
    if sort_order is None:
        sort_order = "asc"
    if sort_order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc")

    ws, api_key, ctx_err = _select_context(workspace_id)
    if ctx_err:
        return ctx_err

    tool_name = "serp-organic-locations-list"
    vendor_endpoint = "/v3/serp/google/organic/locations"

    # create tool_call queued
    tool_calls = _load("tool_calls.json")
    tc_id = _gen_id("dfs_tc_")
    tool_calls.append({
        "id": tc_id,
        "workspace_id": ws.get("id"),
        "api_key_id": api_key.get("id") if api_key else "",
        "tool_name": tool_name,
        "status": "queued",
        "request_payload": {},
        "vendor_endpoint": vendor_endpoint,
        "vendor_http_status": None,
        "error_code": None,
        "error_message": None,
        "estimated_cost_usd": 0.0,  # free endpoint
        "actual_cost_usd": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    })
    _save("tool_calls.json", tool_calls)

    # auth enforcement
    if ws.get("status") != "active" or api_key is None or api_key.get("status") != "active":
        # fail tool_call + task
        tool_calls = _load("tool_calls.json")
        tc = next((r for r in tool_calls if r.get("id") == tc_id), None)
        if tc:
            tc["status"] = "failed"
            tc["error_code"] = "authorization_failed"
            tc["error_message"] = "workspace or api key is not active"
            tc["vendor_http_status"] = 401
            tc["finished_at"] = now
            tc["updated_at"] = now
            _save("tool_calls.json", tool_calls)

        serp_tasks = _load("serp_tasks.json")
        if not any(x.get("tool_call_id") == tc_id for x in serp_tasks):
            serp_tasks.append({
                "id": _gen_id("dfs_st_"),
                "tool_call_id": tc_id,
                "workspace_id": ws.get("id"),
                "task_kind": "locations_list",
                "status": "failed",
                "vendor_task_id": None,
                "request_params": {
                    "country_code": country_code,
                    "search": search,
                    "limit": limit,
                    "offset": offset,
                    "sort_by": sort_by,
                    "sort_order": sort_order,
                },
                "response_payload": None,
                "created_at": now,
                "updated_at": now
            })
            _save("serp_tasks.json", serp_tasks)
        return _err("UNAUTHORIZED", "workspace/api key not authorized for this operation")

    # quota checks (request count; cost is 0)
    if (ws.get("requests_used_month", 0) + 1) > ws.get("monthly_request_limit", 0):
        tool_calls = _load("tool_calls.json")
        tc = next((r for r in tool_calls if r.get("id") == tc_id), None)
        if tc:
            tc["status"] = "failed"
            tc["error_code"] = "quota_exceeded"
            tc["error_message"] = "monthly request quota exceeded"
            tc["vendor_http_status"] = 429
            tc["finished_at"] = now
            tc["updated_at"] = now
            _save("tool_calls.json", tool_calls)

        serp_tasks = _load("serp_tasks.json")
        if not any(x.get("tool_call_id") == tc_id for x in serp_tasks):
            serp_tasks.append({
                "id": _gen_id("dfs_st_"),
                "tool_call_id": tc_id,
                "workspace_id": ws.get("id"),
                "task_kind": "locations_list",
                "status": "failed",
                "vendor_task_id": None,
                "request_params": {
                    "country_code": country_code,
                    "search": search,
                    "limit": limit,
                    "offset": offset,
                    "sort_by": sort_by,
                    "sort_order": sort_order,
                },
                "response_payload": None,
                "created_at": now,
                "updated_at": now
            })
            _save("serp_tasks.json", serp_tasks)
        return _err("QUOTA_EXCEEDED", "monthly quota exceeded")

    # charge request count
    workspaces = _load("workspaces.json")
    ws_row = next((w for w in workspaces if w.get("id") == ws.get("id")), None)
    if ws_row is None:
        return _err("NOT_FOUND", "workspace not found")
    ws_row["requests_used_month"] = int(ws_row.get("requests_used_month", 0)) + 1
    ws_row["updated_at"] = now
    _save("workspaces.json", workspaces)

    # transition to running
    tool_calls = _load("tool_calls.json")
    tc = next((r for r in tool_calls if r.get("id") == tc_id), None)
    if tc is None:
        return _err("NOT_FOUND", "tool_call not found")
    tc["status"] = "running"
    tc["started_at"] = now
    tc["updated_at"] = now
    _save("tool_calls.json", tool_calls)

    # caching: reuse recent succeeded locations_list task in same workspace within TTL
    TTL_SECONDS = 7 * 24 * 3600
    serp_tasks = _load("serp_tasks.json")
    cached = None
    def _parse_iso(z):
        try:
            if z and z.endswith("Z"):
                z = z[:-1]
            return datetime.datetime.fromisoformat(z)
        except Exception:
            return None

    now_dt = _parse_iso(now) or datetime.datetime.utcnow()
    for st in serp_tasks:
        if st.get("workspace_id") != ws.get("id"):
            continue
        if st.get("task_kind") != "locations_list":
            continue
        if st.get("status") != "succeeded":
            continue
        created = _parse_iso(st.get("created_at"))
        if created is None:
            continue
        age = (now_dt - created).total_seconds()
        if age <= TTL_SECONDS and isinstance(st.get("response_payload"), dict):
            cached = st
            break

    # create serp_task for this tool_call (must exist exactly one)
    if any(x.get("tool_call_id") == tc_id for x in serp_tasks):
        return _err("CONFLICT", "serp_task already exists for tool_call_id", tool_call_id=tc_id)

    st_id = _gen_id("dfs_st_")
    task = {
        "id": st_id,
        "tool_call_id": tc_id,
        "workspace_id": ws.get("id"),
        "task_kind": "locations_list",
        "status": "running",
        "vendor_task_id": None,
        "request_params": {
            "country_code": country_code,
            "search": search,
            "limit": limit,
            "offset": offset,
            "sort_by": sort_by,
            "sort_order": sort_order,
        },
        "response_payload": None,
        "created_at": now,
        "updated_at": now
    }
    serp_tasks.append(task)
    _save("serp_tasks.json", serp_tasks)

    # Build or reuse response payload
    if cached is not None:
        locations = cached.get("response_payload", {}).get("locations", [])
    else:
        # offline location catalog
        base = [
            {"location_name": "United States", "location_code": 2840, "country_code": "US"},
            {"location_name": "United Kingdom", "location_code": 2826, "country_code": "GB"},
            {"location_name": "Canada", "location_code": 2124, "country_code": "CA"},
            {"location_name": "Australia", "location_code": 2036, "country_code": "AU"},
            {"location_name": "Germany", "location_code": 2276, "country_code": "DE"},
            {"location_name": "France", "location_code": 2250, "country_code": "FR"},
            {"location_name": "London,England,United Kingdom", "location_code": 1006886, "country_code": "GB"},
            {"location_name": "New York,New York,United States", "location_code": 1023191, "country_code": "US"},
            {"location_name": "San Francisco,California,United States", "location_code": 1023190, "country_code": "US"},
            {"location_name": "Toronto,Ontario,Canada", "location_code": 1008014, "country_code": "CA"},
        ]
        # expand deterministically
        locations = list(base)
        for i in range(1, 301):
            cc = ["US", "GB", "CA", "AU", "DE", "FR"][i % 6]
            locations.append({
                "location_name": f"Location {i} ({cc})",
                "location_code": 900000 + i,
                "country_code": cc
            })

    # filtering
    filtered = locations
    if country_code:
        filtered = [x for x in filtered if x.get("country_code") == country_code]
    if search:
        s = search.strip().lower()
        if s:
            def _match(x):
                return (s in str(x.get("location_name", "")).lower()
                        or s in str(x.get("location_code", "")).lower()
                        or s in str(x.get("country_code", "")).lower())
            filtered = [x for x in filtered if _match(x)]

    # sort
    reverse = (sort_order == "desc")
    filtered.sort(key=lambda x: (x.get(sort_by) is None, x.get(sort_by)), reverse=reverse)

    total = len(filtered)
    page = filtered[offset: offset + limit]

    response_payload = {
        "version": "offline-1",
        "status_code": 20000,
        "status_message": "Ok",
        "time": now,
        "locations": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "offset": offset,
            "has_more": (offset + limit) < total
        },
        "cached": cached is not None
    }

    # finalize task
    serp_tasks = _load("serp_tasks.json")
    st = next((x for x in serp_tasks if x.get("id") == st_id), None)
    if st is None:
        return _err("NOT_FOUND", "serp_task not found")
    st["status"] = "succeeded"
    st["response_payload"] = response_payload
    st["updated_at"] = now
    _save("serp_tasks.json", serp_tasks)

    # finalize tool_call
    tool_calls = _load("tool_calls.json")
    tc = next((r for r in tool_calls if r.get("id") == tc_id), None)
    if tc is None:
        return _err("NOT_FOUND", "tool_call not found")
    tc["status"] = "succeeded"
    tc["vendor_http_status"] = 200
    tc["actual_cost_usd"] = 0.0
    tc["finished_at"] = now
    tc["updated_at"] = now
    _save("tool_calls.json", tool_calls)

    # update api_key last_used_at
    api_keys = _load("api_keys.json")
    if api_key is not None:
        for k in api_keys:
            if k.get("id") == api_key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "tool_call": tc,
        "task": st,
        "data": response_payload,
        "meta": {"latency_ms": latency_ms}
    }

def workspaces_list(api_key, status=None, plan=None, limit=None, offset=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0555000" if __import__("os").path.isdir("./environment_mix/0555000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    start = time.time()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required", field="api_key")
    if status is not None and status not in ("active", "suspended", "closed"):
        return _err("VALIDATION_ERROR", "invalid status filter", field="status")
    if plan is not None and not isinstance(plan, str):
        return _err("VALIDATION_ERROR", "plan must be a string", field="plan")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")
    if offset is None:
        offset = 0
    if not isinstance(offset, int) or offset < 0:
        return _err("VALIDATION_ERROR", "offset must be an integer >= 0", field="offset")
    if sort_by is None:
        sort_by = "created_at"
    if sort_by not in ("created_at", "updated_at", "name"):
        return _err("VALIDATION_ERROR", "invalid sort_by", field="sort_by")
    if sort_order is None:
        sort_order = "asc"
    if sort_order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "invalid sort_order", field="sort_order")

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    tool_calls = _load("tool_calls.json")

    # Authenticate: match by id or by client-visible value stored in key_hash (plaintext stored here by design note)
    key_row = next((k for k in api_keys if k.get("id") == api_key or k.get("key_hash") == api_key), None)
    if not key_row:
        return _err("UNAUTHORIZED", "API key is missing or invalid")

    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is not active", api_key_status=key_row.get("status"))

    ws_id = key_row.get("workspace_id")
    ws = next((w for w in workspaces if w.get("id") == ws_id), None)
    if not ws:
        return _err("UNAUTHORIZED", "API key workspace not found")

    # Log this read as a tool_calls row (best effort; tool_name not in enum so use a mapped vendor tool call)
    # Use 0 estimated cost
    tc_id = f"dfs_tc_{re.sub('[^0-9A-F]', '', os.urandom(12).hex().upper())}"
    ts = _now()
    log_row = {
        "id": tc_id,
        "workspace_id": ws_id,
        "api_key_id": key_row.get("id"),
        "tool_name": "serp-organic-locations-list",  # mapped for audit enum compatibility
        "status": "succeeded",
        "request_payload": {},
        "vendor_endpoint": "/workspaces/list",
        "vendor_http_status": 200,
        "error_code": None,
        "error_message": None,
        "estimated_cost_usd": 0.0,
        "actual_cost_usd": 0.0,
        "started_at": ts,
        "finished_at": ts,
        "created_at": ts,
        "updated_at": ts,
    }
    tool_calls.append(log_row)

    # Update last_used_at
    key_row["last_used_at"] = ts
    key_row["updated_at"] = ts
    _save("api_keys.json", api_keys)
    _save("tool_calls.json", tool_calls)

    # Visible workspaces: in this datastore, a key maps to exactly one workspace
    rows = [ws]

    # Filters
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if plan is not None:
        rows = [r for r in rows if r.get("plan") == plan]

    # Sort
    reverse = (sort_order == "desc")

    def _sort_key(r):
        v = r.get(sort_by)
        return "" if v is None else v

    rows_sorted = sorted(rows, key=_sort_key, reverse=reverse)

    total = len(rows_sorted)
    page = rows_sorted[offset: offset + limit]
    has_more = offset + limit < total

    latency_ms = int((time.time() - start) * 1000)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "offset": offset,
            "has_more": has_more,
            "latency_ms": latency_ms,
        },
    }

def workspaces_create(api_key, name, plan, monthly_request_limit, monthly_cost_usd_limit, status=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0555000" if __import__("os").path.isdir("./environment_mix/0555000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _unwrap_rows(data):
        if isinstance(data, dict) and isinstance(data.get("rows"), list):
            return data["rows"], data
        if isinstance(data, list):
            return data, None
        return [], None

    def _persist(filename, rows, wrapper):
        if wrapper is None:
            _save(filename, rows)
        else:
            wrapper["rows"] = rows
            _save(filename, wrapper)

    def _gen_id(prefix):
        return prefix + uuid.uuid4().hex.upper()[:24]

    def _append_request_log(tool_name_x, workspace_id_x, api_key_id_x, status_x, error_code_x=None, error_message_x=None):
        logs_data = _load("request_logs.json")
        logs_rows, logs_wrap = _unwrap_rows(logs_data)
        logs_rows.append({
            "id": _gen_id("dfs_rl_"),
            "timestamp": now,
            "tool_name": tool_name_x,
            "workspace_id": workspace_id_x,
            "api_key_id": api_key_id_x,
            "status": status_x,
            "error_code": error_code_x,
            "error_message": error_message_x,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _persist("request_logs.json", logs_rows, logs_wrap)

    def _normalize_name(s):
        return " ".join(s.strip().split())

    # ---- Validate inputs ----
    if not isinstance(api_key, str) or not api_key.strip():
        _append_request_log("workspaces-create", None, None, "failed", "validation_error", "api_key is required")
        return _err("VALIDATION_ERROR", "api_key is required", field="api_key")
    if not isinstance(name, str) or not (1 <= len(name.strip()) <= 200):
        _append_request_log("workspaces-create", None, None, "failed", "validation_error", "name must be 1..200 characters")
        return _err("VALIDATION_ERROR", "name must be 1..200 characters", field="name")
    if not isinstance(plan, str) or not (1 <= len(plan.strip()) <= 64):
        _append_request_log("workspaces-create", None, None, "failed", "validation_error", "plan must be 1..64 characters")
        return _err("VALIDATION_ERROR", "plan must be 1..64 characters", field="plan")

    if not isinstance(monthly_request_limit, int) or monthly_request_limit < 0:
        _append_request_log("workspaces-create", None, None, "failed", "validation_error", "monthly_request_limit must be an integer >= 0")
        return _err("VALIDATION_ERROR", "monthly_request_limit must be an integer >= 0", field="monthly_request_limit")

    if not isinstance(monthly_cost_usd_limit, (int, float)) or float(monthly_cost_usd_limit) < 0:
        _append_request_log("workspaces-create", None, None, "failed", "validation_error", "monthly_cost_usd_limit must be a number >= 0")
        return _err("VALIDATION_ERROR", "monthly_cost_usd_limit must be a number >= 0", field="monthly_cost_usd_limit")

    if status is None:
        status = "active"
    if status not in ("active", "suspended"):
        _append_request_log("workspaces-create", None, None, "failed", "validation_error", "status must be one of: active, suspended")
        return _err("VALIDATION_ERROR", "status must be one of: active, suspended", field="status")

    # Plan must match schema enum
    if plan not in ("free", "pro", "enterprise"):
        _append_request_log("workspaces-create", None, None, "failed", "validation_error", "plan must be one of: free, pro, enterprise")
        return _err("VALIDATION_ERROR", "plan must be one of: free, pro, enterprise", field="plan")

    # ---- Authenticate api_key (explicit credential) ----
    api_keys_data = _load("api_keys.json")
    api_keys_rows, api_keys_wrap = _unwrap_rows(api_keys_data)

    # Parameter can match id (client-visible) OR key_hash row value (also client-visible in this store model)
    caller_key = None
    for k in api_keys_rows:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            caller_key = k
            break
    if not caller_key or caller_key.get("status") != "active":
        _append_request_log("workspaces-create", None, caller_key.get("id") if caller_key else None, "failed", "auth_failed", "Invalid or inactive API key")
        return _err("UNAUTHORIZED", "Invalid or inactive API key", field="api_key")

    # ---- Load workspaces and enforce unique(name) with normalization ----
    workspaces_data = _load("workspaces.json")
    workspaces_rows, workspaces_wrap = _unwrap_rows(workspaces_data)

    norm_name = _normalize_name(name)
    for w in workspaces_rows:
        if isinstance(w, dict) and _normalize_name(str(w.get("name", ""))) == norm_name:
            _append_request_log("workspaces-create", None, caller_key.get("id"), "failed", "conflict", "Workspace name already exists")
            return _err("CONFLICT", "Workspace name already exists (unique(name))", field="name", rule="unique(name)")

    # ---- Create workspace ----
    ws_id = _gen_id("dfs_ws_")
    new_ws = {
        "id": ws_id,
        "name": norm_name,
        "status": status,
        "plan": plan,
